-- hrm.loan_installments: Frozen by trigger once status = deducted.
drop function if exists hrm.todo_loan_installments_freeze();
create or replace function hrm.tg_loan_installments_freeze() returns trigger
language plpgsql as $fn$
declare
    v_final constant text[] := array['locked', 'paid', 'posted', 'closed'];
    v_free constant text[] := array['status', 'updated_at', 'updated_by', 'row_version'];
    v_run text;
begin
    if tg_op = 'DELETE' then
        if old.status <> 'scheduled' or old.pay_result_line_id is not null then
            raise exception 'loan installment %: a recovered, skipped or used installment is never deleted', old.id
                using errcode = '23514', constraint = 'ck_loan_installments_frozen';
        end if;
        return old;
    end if;
    if old.status in ('deducted', 'settled_early') then
        raise exception 'loan installment %: a recovered installment never changes (FR-XM-05)', old.id
            using errcode = '23514', constraint = 'ck_loan_installments_frozen';
    end if;
    if old.pay_result_line_id is not null then
        select r.status into v_run
          from hrm.pay_result_lines l
          join hrm.pay_results x on x.id = l.result_id
          join hrm.pay_runs r on r.id = x.pay_run_id
         where l.id = old.pay_result_line_id
           for share of r;
        if v_run = any (v_final)
           and (new.status <> 'deducted' or (to_jsonb(new) - v_free) is distinct from (to_jsonb(old) - v_free)) then
            raise exception 'loan installment %: the pay run that took it is locked; the installment only becomes deducted (FR-XM-26)', old.id
                using errcode = '23514', constraint = 'ck_loan_installments_frozen';
        end if;
    end if;
    return new;
end
$fn$;
drop trigger if exists tg_loan_installments_freeze on hrm.loan_installments;
create trigger tg_loan_installments_freeze before update or delete on hrm.loan_installments
    for each row execute function hrm.tg_loan_installments_freeze();
comment on table hrm.loan_installments is 'Requirements: LON-03. Rule (implemented in S1.41): Frozen by trigger once status = deducted. Source: hrm-pay.yaml.';
comment on column hrm.loan_installments.loan_id is 'fk hrm.loans';
comment on column hrm.loan_installments.pay_period_id is 'fk hrm.pay_periods';
comment on column hrm.loan_installments.pay_result_line_id is 'fk hrm.pay_result_lines';

-- hrm.loan_transactions: trigger: a recovery cannot exceed the outstanding balance
drop function if exists hrm.todo_loan_transactions_recovery_within_balance();
create or replace function hrm.tg_loan_transactions_recovery_within_balance() returns trigger
language plpgsql as $fn$
declare
    v_company uuid;
    v_balance numeric(19,4);
begin
    select l.company_id into v_company from hrm.loans l where l.id = new.loan_id for update;
    if v_company is null or v_company <> new.company_id then
        raise exception 'loan ledger: the entry does not belong to a loan of this company'
            using errcode = '23514', constraint = 'ck_loan_transactions_balance';
    end if;
    if new.amount = 0
       or (new.kind = 'disbursement' and new.amount < 0)
       or (new.kind in ('recovery', 'early_settlement', 'settlement_recovery', 'write_off') and new.amount > 0) then
        raise exception 'loan ledger: the amount of a % entry has the wrong sign or is zero', new.kind
            using errcode = '23514', constraint = 'ck_loan_transactions_balance';
    end if;
    if new.kind = 'disbursement' and exists (select 1 from hrm.loan_transactions t where t.loan_id = new.loan_id and t.kind = 'disbursement') then
        raise exception 'loan ledger: the loan was disbursed already'
            using errcode = '23514', constraint = 'ck_loan_transactions_balance';
    end if;
    select coalesce(sum(t.amount), 0) into v_balance from hrm.loan_transactions t where t.loan_id = new.loan_id;
    if v_balance + new.amount < 0 then
        raise exception 'loan ledger: a recovery cannot exceed the outstanding balance (%)', v_balance
            using errcode = '23514', constraint = 'ck_loan_transactions_balance';
    end if;
    return new;
end
$fn$;
drop trigger if exists tg_loan_transactions_recovery_within_balance on hrm.loan_transactions;
create trigger tg_loan_transactions_recovery_within_balance before insert on hrm.loan_transactions
    for each row execute function hrm.tg_loan_transactions_recovery_within_balance();
comment on table hrm.loan_transactions is 'Loan ledger (disbursement, recovery, adjustment, write-off); balance is the sum. Requirements: LON-03, LON-05, LON-07. Rule (implemented in S1.41): trigger: a recovery cannot exceed the outstanding balance Recovery entries are written only when the pay run locks. Source: hrm-pay.yaml.';
comment on column hrm.loan_transactions.loan_id is 'fk hrm.loans';
comment on column hrm.loan_transactions.amount is 'positive increases balance';
